// Small TLS front for the remote E2E (tests only, 127.0.0.1 only): https://127.0.0.1:<port> →
// http://<target>. Self-signed certificate (openssl, generated by the E2E script), host header stays.
//
//   node tls-proxy.mjs <port> <target-host:port> <cert.pem> <key.pem>
import https from "node:https";
import http from "node:http";
import fs from "node:fs";

const [port, target, cert, key] = process.argv.slice(2);
const [thost, tport] = target.split(":");
const server = https.createServer({ cert: fs.readFileSync(cert), key: fs.readFileSync(key) }, (req, res) => {
  const up = http.request(
    { host: thost, port: Number(tport), method: req.method, path: req.url, headers: { ...req.headers, "x-forwarded-proto": "https" } },
    (r) => {
      res.writeHead(r.statusCode, r.headers);
      r.pipe(res);
    },
  );
  up.on("error", (e) => {
    res.writeHead(502, { "content-type": "text/plain" });
    res.end("bad gateway: " + e.message);
  });
  req.pipe(up);
});
server.listen(Number(port), "127.0.0.1", () => console.log(`tls-proxy https://127.0.0.1:${port} -> http://${target}`));
